import{_ as r,c as t,o,ah as i}from"./chunks/framework.DX1DJjtl.js";const h=JSON.parse('{"title":"Render","description":"","frontmatter":{},"headers":[],"relativePath":"api/core/Render.md","filePath":"api/core/Render.md","lastUpdated":1785349141000}'),n={name:"api/core/Render.md"};function s(l,e,a,d,p,c){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="render" tabindex="-1">Render <a class="header-anchor" href="#render" aria-label="Permalink to &quot;Render&quot;">​</a></h1><p>Render buffer for Basalt.</p><p>Holds the screen as three string arrays (text / fg / bg). Colors are stored as raw bytes (registry indices from core/palette), which is what allows more than 16 colors in the buffer. On flush, only lines that actually differ from what the terminal currently shows are blitted, and color bytes are translated to blit hex chars through the palette mapper.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><h3 id="renderlinebuffer" tabindex="-1"><code>RenderLineBuffer</code> <a class="header-anchor" href="#renderlinebuffer" aria-label="Permalink to &quot;`RenderLineBuffer`&quot;">​</a></h3><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RenderLineBuffer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> string[]</span></span></code></pre></div><h3 id="renderpixelrows" tabindex="-1"><code>RenderPixelRows</code> <a class="header-anchor" href="#renderpixelrows" aria-label="Permalink to &quot;`RenderPixelRows`&quot;">​</a></h3><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RenderPixelRows </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> string[]</span></span></code></pre></div><h3 id="renderpixelpalette" tabindex="-1"><code>RenderPixelPalette</code> <a class="header-anchor" href="#renderpixelpalette" aria-label="Permalink to &quot;`RenderPixelPalette`&quot;">​</a></h3><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RenderPixelPalette </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">integer, string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="renderterminal" tabindex="-1"><code>RenderTerminal</code> <a class="header-anchor" href="#renderterminal" aria-label="Permalink to &quot;`RenderTerminal`&quot;">​</a></h3><p><em>extends PaletteTerminal</em></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>getSize</td><td><code>fun(): integer, integer</code></td><td></td></tr><tr><td>setCursorPos</td><td><code>fun(x: number, y: number)</code></td><td></td></tr><tr><td>setCursorBlink</td><td><code>fun(blink: boolean)</code></td><td></td></tr><tr><td>setTextColor</td><td><code>fun(color: number)</code></td><td></td></tr><tr><td>blit</td><td><code>fun(text: string, foreground: string, background: string)</code></td><td></td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="render-new-t" tabindex="-1">Render.new(t) <a class="header-anchor" href="#render-new-t" aria-label="Permalink to &quot;Render.new(t)&quot;">​</a></h3><p>Creates a retained terminal render buffer.</p><ul><li><p><strong>t</strong> (<code>RenderTerminal</code>) Terminal-like target</p></li><li><p><strong>returns</strong> <strong>buffer</strong> (<code>Render</code>)</p></li></ul><h3 id="render-resize-w-h" tabindex="-1">Render:resize(w, h) <a class="header-anchor" href="#render-resize-w-h" aria-label="Permalink to &quot;Render:resize(w, h)&quot;">​</a></h3><p>Resizes and clears the retained buffer.</p><ul><li><p><strong>w</strong> (<code>integer</code>) Width</p></li><li><p><strong>h</strong> (<code>integer</code>) Height</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-push-x-y-w-h" tabindex="-1">Render:push(x, y, w, h) <a class="header-anchor" href="#render-push-x-y-w-h" aria-label="Permalink to &quot;Render:push(x, y, w, h)&quot;">​</a></h3><p>Pushes a child region: translates the origin to (x, y) in the current space and intersects the clip rect with the w*h area.</p><ul><li><p><strong>x</strong> (<code>number</code>) Child x position</p></li><li><p><strong>y</strong> (<code>number</code>) Child y position</p></li><li><p><strong>w</strong> (<code>number</code>) Child width</p></li><li><p><strong>h</strong> (<code>number</code>) Child height</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-pop" tabindex="-1">Render:pop() <a class="header-anchor" href="#render-pop" aria-label="Permalink to &quot;Render:pop()&quot;">​</a></h3><p>Restores the previous origin and clipping rectangle.</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul><h3 id="render-write-x-y-str-fgchar-bgchar" tabindex="-1">Render:write(x, y, str, fgChar, bgChar) <a class="header-anchor" href="#render-write-x-y-str-fgchar-bgchar" aria-label="Permalink to &quot;Render:write(x, y, str, fgChar, bgChar)&quot;">​</a></h3><p>Core write. fgChar/bgChar are single-byte strings or nil (keep existing).</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text to write</p></li><li><p><strong>fgChar</strong> (<code>string</code>, optional) Encoded foreground bytes</p></li><li><p><strong>bgChar</strong> (<code>string</code>, optional) Encoded background bytes</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-blit-x-y-str-fg-bg" tabindex="-1">Render:blit(x, y, str, fg, bg) <a class="header-anchor" href="#render-blit-x-y-str-fg-bg" aria-label="Permalink to &quot;Render:blit(x, y, str, fg, bg)&quot;">​</a></h3><p>Writes text with optional fg/bg colors (public color values, nil = keep).</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text to write</p></li><li><p><strong>fg</strong> (<code>number|false</code>, optional) Foreground color; false keeps the existing color</p></li><li><p><strong>bg</strong> (<code>number|false</code>, optional) Background color; false keeps the existing color</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-colorblit-x-y-str-foregrounds-backgrounds" tabindex="-1">Render:colorBlit(x, y, str, foregrounds, backgrounds) <a class="header-anchor" href="#render-colorblit-x-y-str-foregrounds-backgrounds" aria-label="Permalink to &quot;Render:colorBlit(x, y, str, foregrounds, backgrounds)&quot;">​</a></h3><p>Writes a row whose cells may each use a different public color value. This is the efficient path for custom-painted editors and charts: it performs one clipped line splice instead of one splice per cell.</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text to write</p></li><li><p><strong>foregrounds</strong> (<code>number[]</code>) Foreground color for each character</p></li><li><p><strong>backgrounds</strong> (<code>number[]</code>) Background color for each character</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-drawtext-x-y-str" tabindex="-1">Render:drawText(x, y, str) <a class="header-anchor" href="#render-drawtext-x-y-str" aria-label="Permalink to &quot;Render:drawText(x, y, str)&quot;">​</a></h3><p>Writes plain text, keeping the colors underneath. (named drawText because .text is the buffer&#39;s line array)</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text to write</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-rawblit-x-y-str-fgstr-bgstr" tabindex="-1">Render:rawBlit(x, y, str, fgStr, bgStr) <a class="header-anchor" href="#render-rawblit-x-y-str-fgstr-bgstr" aria-label="Permalink to &quot;Render:rawBlit(x, y, str, fgStr, bgStr)&quot;">​</a></h3><p>Writes a pre-encoded span: fgStr/bgStr are byte strings (registry indices) with the same length as str, or nil to keep existing colors.</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text to write</p></li><li><p><strong>fgStr</strong> (<code>string</code>, optional) Encoded foreground bytes</p></li><li><p><strong>bgStr</strong> (<code>string</code>, optional) Encoded background bytes</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-maskedblit-x-y-str-fgstr-bgstr-textmask-fgmask-bgmask" tabindex="-1">Render:maskedBlit(x, y, str, fgStr, bgStr, textMask, fgMask, bgMask) <a class="header-anchor" href="#render-maskedblit-x-y-str-fgstr-bgstr-textmask-fgmask-bgmask" aria-label="Permalink to &quot;Render:maskedBlit(x, y, str, fgStr, bgStr, textMask, fgMask, bgMask)&quot;">​</a></h3><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text plane</p></li><li><p><strong>fgStr</strong> (<code>string</code>, optional) Encoded foreground plane</p></li><li><p><strong>bgStr</strong> (<code>string</code>, optional) Encoded background plane</p></li><li><p><strong>textMask</strong> (<code>string</code>, optional) Text visibility mask</p></li><li><p><strong>fgMask</strong> (<code>string</code>, optional) Foreground visibility mask</p></li><li><p><strong>bgMask</strong> (<code>string</code>, optional) Background visibility mask</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-drawpixels-x-y-pixelwidth-pixelheight-rows-palettebytes" tabindex="-1">Render:drawPixels(x, y, pixelWidth, pixelHeight, rows, paletteBytes) <a class="header-anchor" href="#render-drawpixels-x-y-pixelwidth-pixelheight-rows-palettebytes" aria-label="Permalink to &quot;Render:drawPixels(x, y, pixelWidth, pixelHeight, rows, paletteBytes)&quot;">​</a></h3><ul><li><p><strong>x</strong> (<code>number</code>) X position in terminal cells</p></li><li><p><strong>y</strong> (<code>number</code>) Y position in terminal cells</p></li><li><p><strong>pixelWidth</strong> (<code>integer</code>) Source width in virtual pixels</p></li><li><p><strong>pixelHeight</strong> (<code>integer</code>) Source height in virtual pixels</p></li><li><p><strong>rows</strong> (<code>RenderPixelRows</code>) Palette-index rows; byte zero is transparent</p></li><li><p><strong>paletteBytes</strong> (<code>RenderPixelPalette</code>) Palette index to registry byte</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-drawblit-x-y-str-fghex-bghex" tabindex="-1">Render:drawBlit(x, y, str, fgHex, bgHex) <a class="header-anchor" href="#render-drawblit-x-y-str-fghex-bghex" aria-label="Permalink to &quot;Render:drawBlit(x, y, str, fgHex, bgHex)&quot;">​</a></h3><p>Writes a blit triple with hex color strings (&quot;0&quot;-&quot;f&quot;), e.g. straight from window.getLine() — used to embed foreign terminal content.</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>str</strong> (<code>string</code>) Text to write</p></li><li><p><strong>fgHex</strong> (<code>string</code>, optional) Foreground blit string</p></li><li><p><strong>bgHex</strong> (<code>string</code>, optional) Background blit string</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-fill-x-y-w-h-ch-fg-bg" tabindex="-1">Render:fill(x, y, w, h, ch, fg, bg) <a class="header-anchor" href="#render-fill-x-y-w-h-ch-fg-bg" aria-label="Permalink to &quot;Render:fill(x, y, w, h, ch, fg, bg)&quot;">​</a></h3><p>Fills a w*h area with a character and optional colors.</p><ul><li><p><strong>x</strong> (<code>number</code>) X position</p></li><li><p><strong>y</strong> (<code>number</code>) Y position</p></li><li><p><strong>w</strong> (<code>number</code>) Width</p></li><li><p><strong>h</strong> (<code>number</code>) Height</p></li><li><p><strong>ch</strong> (<code>string</code>) Fill character</p></li><li><p><strong>fg</strong> (<code>number|false</code>, optional) Foreground color; false keeps the existing color</p></li><li><p><strong>bg</strong> (<code>number|false</code>, optional) Background color; false keeps the existing color</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-setcursor-x-y-blink-color" tabindex="-1">Render:setCursor(x, y, blink, color) <a class="header-anchor" href="#render-setcursor-x-y-blink-color" aria-label="Permalink to &quot;Render:setCursor(x, y, blink, color)&quot;">​</a></h3><p>Stores the cursor state to present during the next flush.</p><ul><li><p><strong>x</strong> (<code>number</code>) Cursor x</p></li><li><p><strong>y</strong> (<code>number</code>) Cursor y</p></li><li><p><strong>blink</strong> (<code>boolean</code>) Blink state</p></li><li><p><strong>color</strong> (<code>number</code>, optional) Cursor color</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="render-flush" tabindex="-1">Render:flush() <a class="header-anchor" href="#render-flush" aria-label="Permalink to &quot;Render:flush()&quot;">​</a></h3><p>Diffs the buffer against the terminal state and blits changed lines only.</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul>',57)])])}const u=r(n,[["render",s]]);export{h as __pageData,u as default};
